-- =============================================================================
-- V84：需求管理系统清单主数据（req_system）初始化
-- -----------------------------------------------------------------------------
-- 数据来源：用户提供《系统清单》参考信息（序号 1-416，事业群/系统编号/英文简称/
-- 系统名称/状态/逻辑子系统/业务组件/业务领域/产品视图/投产点/系统介绍/灾备等级/
-- 类别/引入保留），按 req_system 字段映射导入，作为主责/协同系统下拉的数据源。
-- 状态"正常"映射为"启用"；W01812/W0332C 沿用演示数据 id，避免与 mock 冲突。
-- =============================================================================

ON DUPLICATE KEY UPDATE
        system_name = VALUES(system_name),
        english_name = VALUES(english_name),
        conglomerate = VALUES(conglomerate),
        status = VALUES(status),
        logical_subsystem_code = VALUES(logical_subsystem_code),
        logical_subsystem_name = VALUES(logical_subsystem_name),
        business_component_code = VALUES(business_component_code),
        business_component_name = VALUES(business_component_name),
        business_domain = VALUES(business_domain),
        product_view = VALUES(product_view),
        launch_point = VALUES(launch_point),
        category = VALUES(category),
        introduction = VALUES(introduction),
        disaster_level = VALUES(disaster_level),
        source_type = VALUES(source_type);
